from rdkit import Chem

# Parse the input SMILES
smiles = "Cc1c(C(=O)Nc2ccc(-c3nc(Br)cnc3N)cc2)c(=O)n(-c2ccccc2)n1C"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("SMILES is valid")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Print atom types and connectivity
    for atom in mol.GetAtoms():
        print(f"Atom {atom.GetIdx()}: {atom.GetSymbol()}, aromatic={atom.GetIsAromatic()}, degree={atom.GetDegree()}")

    # Find bonds
    print("\nBonds:")
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.AROMATIC:
            print(f"  {bond.GetBeginAtomIdx()}-{bond.GetEndAtomIdx()} (aromatic)")
else:
    print("Invalid SMILES")
EOF
"}

